import fs from 'node:fs';
import http from 'node:http';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
const repo = '/Users/jakefitzgerald/.codex/worktrees/3c6b/text-to-cad';
const scratch = '/private/tmp/cadgen-performance-20260910';
const work = `${repo}/models/tmp/surface-culling-ab-20260910`;
const output = `${repo}/scripts/bench/cadgen-performance/results/viewer-surface-culling-ab-20260910.json`;
const require = createRequire(`${repo}/packages/cadgen-js/package.json`);
const { chromium } = require('playwright');
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const paths = {
  '/': `${work}/index.html`,
  '/scene.mjs': `${scratch}/surface-culling-scene.mjs`,
  '/shared/cadSurfaceInstances.js': `${repo}/packages/cadgen-js/src/common/cadSurfaceInstances.js`,
  '/three/three.module.js': `${repo}/packages/cadgen-js/node_modules/three/build/three.module.js`,
  '/three/three.core.js': `${repo}/packages/cadgen-js/node_modules/three/build/three.core.js`,
};
const sourcePaths = [...Object.values(paths), `${repo}/packages/cadgen-js/package-lock.json`, fileURLToPath(import.meta.url)];
const manifest = () => Object.fromEntries(sourcePaths.map(path => [path, { bytes: fs.statSync(path).size, sha256: sha(fs.readFileSync(path)) }]));
const initial = manifest();
const report = { startedUtc: new Date().toISOString(), success: false, qualification: 'Bounded standalone WebGL counterfactual using the actual shared surface-instance builder and locked Three. Same scene/process toggles only frustumCulled; six warmup frames then ABBA BAAB. Framebuffer, draw-count and resource correctness evidence only; no timing or full-hand performance inference. No STEP, SURF, native CAD, LOD, React or viewer runtime.', sourceManifest: initial, helperSource: fs.readFileSync(fileURLToPath(import.meta.url), 'utf8'), sceneHelperSource: fs.readFileSync(paths['/scene.mjs'], 'utf8'), htmlSource: fs.readFileSync(paths['/'], 'utf8'), requests: [], errors: [] };
const server = http.createServer((request, response) => {
  const url = new URL(request.url, 'http://127.0.0.1');
  const path = paths[url.pathname];
  if (!path) { response.writeHead(404); response.end(); return; }
  const payload = fs.readFileSync(path);
  report.requests.push({ path: url.pathname, bytes: payload.length, sha256: sha(payload) });
  response.writeHead(200, { 'Content-Type': url.pathname === '/' ? 'text/html' : 'text/javascript', 'Cache-Control': 'no-store' });
  response.end(payload);
});
let browser;
let guard;
try {
  await new Promise((resolve, reject) => { server.once('error', reject); server.listen(0, '127.0.0.1', resolve); });
  report.serverAddress = server.address();
  browser = await chromium.launch({ headless: true, args: ['--use-angle=metal'] });
  guard = setTimeout(() => { report.guardFired = true; browser.close().catch(() => {}); }, 45000);
  report.browserVersion = browser.version();
  const page = await browser.newPage({ viewport: { width: 640, height: 480 }, deviceScaleFactor: 1 });
  page.on('pageerror', error => report.errors.push(String(error)));
  await page.goto(`http://127.0.0.1:${server.address().port}/`, { waitUntil: 'networkidle', timeout: 15000 });
  await page.waitForFunction(() => typeof window.runSurfaceCullingCheck === 'function', null, { timeout: 15000 });
  report.result = await page.evaluate(() => window.runSurfaceCullingCheck());
  await page.locator('canvas').screenshot({ path: `${work}/frame.png` });
  report.frame = { path: `${work}/frame.png`, sha256: sha(fs.readFileSync(`${work}/frame.png`)) };
  report.cleanup = await page.evaluate(() => window.disposeSurfaceCullingCheck());
  report.sourceManifestAfter = manifest();
  report.sourceUnchanged = JSON.stringify(initial) === JSON.stringify(report.sourceManifestAfter);
  if (!report.sourceUnchanged || report.errors.length || !report.cleanup.setsDisposed) throw new Error('source drift, browser error or incomplete disposal');
  for (const [url, path] of Object.entries(paths)) {
    if (!report.requests.some(row => row.path === url && row.sha256 === initial[path].sha256)) throw new Error(`Missing exact served-byte proof for ${url}`);
  }
  report.success = true;
} catch (error) {
  report.failure = String(error.stack || error);
  process.exitCode = 1;
} finally {
  if (guard) clearTimeout(guard);
  if (browser) { await browser.close(); report.browserClosed = true; }
  await new Promise(resolve => server.close(resolve));
  report.serverClosed = true;
  report.finishedUtc = new Date().toISOString();
  fs.writeFileSync(output, JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify({ success: report.success, output, failure: report.failure, drawRows: report.result?.rows.map(({ culled, renderCalls, renderTriangles, mainClusters, shadowClusters, framebufferSha256 }) => ({ culled, renderCalls, renderTriangles, mainClusters: mainClusters.length, shadowClusters: shadowClusters.length, framebufferSha256 })), assertions: report.result?.assertions, cleanup: report.cleanup }));
}

