import * as THREE from '/three/three.module.js';
import { buildCadSurfaceInstanceSets, dissolveCadSurfaceInstanceSets } from '/shared/cadSurfaceInstances.js';

const assert = (value, message) => { if (!value) throw new Error(message); };
const sha = async (bytes) => [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(x => x.toString(16).padStart(2, '0')).join('');
const jsonSha = value => sha(new TextEncoder().encode(JSON.stringify(value)));
const canvas = document.querySelector('canvas');
const gl = canvas.getContext('webgl2', { antialias: false, preserveDrawingBuffer: true });
assert(gl, 'WebGL2 unavailable');
const resourceCounts = {};
for (const suffix of ['Buffer', 'Texture', 'Program', 'Shader', 'Framebuffer', 'Renderbuffer', 'VertexArray']) {
  for (const prefix of ['create', 'delete']) {
    const name = prefix + suffix;
    if (typeof gl[name] !== 'function') continue;
    resourceCounts[name] = 0;
    const original = gl[name].bind(gl);
    gl[name] = (...args) => { resourceCounts[name] += 1; return original(...args); };
  }
}
const renderer = new THREE.WebGLRenderer({ canvas, context: gl, antialias: false });
renderer.setSize(640, 480, false);
renderer.setPixelRatio(1);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.NoToneMapping;
const target = new THREE.WebGLRenderTarget(640, 480, { depthBuffer: true });
const pixels = new Uint8Array(640 * 480 * 4);
const scene = new THREE.Scene();
scene.background = new THREE.Color('#dce4ef');
scene.add(new THREE.HemisphereLight(0xffffff, 0x586779, 2));
const light = new THREE.DirectionalLight(0xffffff, 3);
light.position.set(-3, 4, 10);
light.castShadow = true;
light.shadow.mapSize.set(512, 512);
Object.assign(light.shadow.camera, { left: -9, right: 9, top: 9, bottom: -9, near: 0.1, far: 40 });
light.shadow.camera.updateProjectionMatrix();
light.shadow.bias = -0.0002;
scene.add(light);
const floor = new THREE.Mesh(new THREE.PlaneGeometry(16, 12), new THREE.MeshStandardMaterial({ color: '#eeeeee', roughness: 1 }));
floor.position.z = -2.5;
floor.receiveShadow = true;
scene.add(floor);
const camera = new THREE.OrthographicCamera(-4, 4, 3, -3, 0.1, 100);
camera.position.z = 10;
camera.updateMatrixWorld(true);
const groups = [];
let currentDraws = null;
for (let cluster = 0; cluster < 48; cluster += 1) {
  const group = new THREE.Group();
  group.name = `cluster-${cluster}`;
  const geometry = new THREE.BoxGeometry(1, 1, 1, 20, 20, 20);
  const records = [];
  for (let slot = 0; slot < 4; slot += 1) {
    const partId = `cluster-${cluster}/instance-${slot}`;
    const material = new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL((cluster * .137 + slot * .025) % 1, .65, .43), roughness: .6, metalness: .05 });
    const mesh = new THREE.Mesh(geometry, material);
    mesh.matrixAutoUpdate = false;
    if (cluster === 3) mesh.matrix.identity();
    else if (cluster === 2) mesh.matrix.set(1, 2, .4, 4.8 + slot * .08, 0, 1, 0, -1 + (slot % 2) * .3, 0, 0, 1, -.2 * slot, 0, 0, 0, 1);
    else mesh.matrix.makeTranslation((slot % 2) * .55, Math.floor(slot / 2) * .55, -.2 * slot);
    mesh.userData = { partId, faceIds: new Uint32Array([cluster * 24 + slot * 6, 6]) };
    group.add(mesh);
    records.push({ partId, mesh, geometry, material, baseColor: material.color.clone(), baseEmissiveIntensity: 0 });
  }
  if (cluster === 0) group.position.set(-1.9, -1.2, 0);
  else if (cluster === 1) group.position.set(.7, .8, .2);
  else if (cluster === 3) {
    group.matrixAutoUpdate = false;
    group.matrix.set(1, 1, 1, 5.3, 0, 1, 0, -1.8, 0, 0, 1, 0, 0, 0, 0, 1);
  } else if (cluster >= 4) group.position.set((cluster % 2 ? -1 : 1) * (35 + cluster * 2), cluster % 7 - 3, 0);
  scene.add(group);
  const sets = buildCadSurfaceInstanceSets(THREE, records, group);
  assert(sets.size === 1, `cluster ${cluster} did not create one actual shared instance set`);
  const set = [...sets][0];
  set.object.onBeforeRender = () => currentDraws?.main.push(cluster);
  set.object.onBeforeShadow = () => currentDraws?.shadow.push(cluster);
  groups.push({ cluster, group, records, geometry, sets, set });
}
scene.updateMatrixWorld(true);
const trianglesPerGeometry = groups[0].geometry.index.count / 3;
assert(trianglesPerGeometry === 4800, 'unexpected fixture triangle count');
const occurrenceTriangles = groups.reduce((sum, x) => sum + x.geometry.index.count / 3 * x.records.length, 0);
assert(occurrenceTriangles <= 1000000 && groups.length <= 64, 'fixture exceeds requested bound');
const references = groups.map(({ set, geometry, records }) => ({
  object: set.object, geometry, material: set.object.material,
  matrix: set.object.instanceMatrix, colors: set.object.instanceColor,
  position: geometry.attributes.position, normal: geometry.attributes.normal, uv: geometry.attributes.uv, index: geometry.index,
  matrixArray: set.object.instanceMatrix.array, colorArray: set.object.instanceColor.array,
  parts: set.object.userData.partIds, faces: set.object.userData.faceIdsByInstance,
  records: records.slice(), faceArrays: records.map(record => record.mesh.userData.faceIds),
}));
const arrays = [];
for (const { set, geometry, records } of groups) {
  arrays.push(geometry.attributes.position.array, geometry.attributes.normal.array, geometry.attributes.uv.array, geometry.index.array, set.object.instanceMatrix.array, set.object.instanceColor.array);
  arrays.push(...records.map(record => record.mesh.userData.faceIds));
}
const byteHashes = () => Promise.all(arrays.map(array => sha(new Uint8Array(array.buffer, array.byteOffset, array.byteLength))));
const identity = () => groups.map(({ set, records }) => ({ object: set.object.uuid, geometry: set.object.geometry.uuid, material: set.object.material.uuid, partIds: set.object.userData.partIds, slots: records.map(record => record.surfaceInstance.slot) }));
function verifyReferences() {
  for (let i = 0; i < groups.length; i += 1) {
    const { set, geometry, records } = groups[i], ref = references[i];
    assert(set.object === ref.object && geometry === ref.geometry && set.object.material === ref.material, 'object/material/geometry replaced');
    assert(set.object.instanceMatrix === ref.matrix && set.object.instanceColor === ref.colors, 'instance attributes replaced');
    assert(set.object.instanceMatrix.array === ref.matrixArray && set.object.instanceColor.array === ref.colorArray, 'instance arrays replaced');
    for (const key of ['position', 'normal', 'uv']) assert(geometry.attributes[key] === ref[key], `geometry ${key} replaced`);
    assert(geometry.index === ref.index && set.object.userData.partIds === ref.parts && set.object.userData.faceIdsByInstance === ref.faces, 'index/metadata replaced');
    assert(!set.disposed && records.every((record, slot) => record === ref.records[slot] && record.surfaceInstance.set === set && record.surfaceInstance.slot === slot && record.mesh.userData.faceIds === ref.faceArrays[slot]), 'occurrence identity changed');
  }
}
function render(culled) {
  for (const { set } of groups) set.object.frustumCulled = culled;
  currentDraws = { main: [], shadow: [] };
  renderer.setRenderTarget(target);
  renderer.render(scene, camera);
  gl.finish();
  renderer.readRenderTargetPixels(target, 0, 0, 640, 480, pixels);
  assert(gl.getError() === gl.NO_ERROR, 'WebGL error');
  const result = { culled, renderCalls: renderer.info.render.calls, renderTriangles: renderer.info.render.triangles, mainClusters: currentDraws.main.slice(), shadowClusters: currentDraws.shadow.slice() };
  currentDraws = null;
  return result;
}
async function run() {
  // Compile and upload every object before comparison, then exercise both modes.
  const warmup = [false, true, false, true, false, true];
  for (const culled of warmup) render(culled);
  const before = { identity: await jsonSha(identity()), bytes: await jsonSha(await byteHashes()), gpuResources: { ...resourceCounts }, renderer: { geometries: renderer.info.memory.geometries, textures: renderer.info.memory.textures, programs: renderer.info.programs.length } };
  const rows = [];
  for (const culled of [false, true, true, false, true, false, false, true]) {
    const row = render(culled);
    row.framebufferSha256 = await sha(pixels);
    row.gpuResources = { ...resourceCounts };
    verifyReferences();
    rows.push(row);
  }
  assert(new Set(rows.map(row => row.framebufferSha256)).size === 1, 'framebuffers differ across culling modes');
  for (const row of rows) {
    assert(JSON.stringify(row.gpuResources) === JSON.stringify(before.gpuResources), 'GPU resources allocated/deleted after warmup');
    assert(row.mainClusters.length === (row.culled ? 4 : 48), 'unexpected main-camera group culling');
    if (row.culled) assert(row.mainClusters.every(cluster => cluster < 4), 'an offscreen group survived expected cull');
  }
  const full = pixels.slice();
  const contributions = [];
  for (const cluster of [0, 2, 3]) {
    groups[cluster].set.object.visible = false;
    render(true);
    let changedPixels = 0;
    for (let i = 0; i < pixels.length; i += 4) if (pixels[i] !== full[i] || pixels[i + 1] !== full[i + 1] || pixels[i + 2] !== full[i + 2] || pixels[i + 3] !== full[i + 3]) changedPixels += 1;
    groups[cluster].set.object.visible = true;
    assert(changedPixels > 20, `cluster ${cluster} contributes no visible framebuffer pixels`);
    contributions.push({ cluster, kind: ['inside', '', 'crossing-frustum', 'sheared-parent'][cluster], changedPixels });
  }
  render(true);
  assert(await sha(pixels) === rows[0].framebufferSha256, 'visibility probes did not restore exact framebuffer');
  verifyReferences();
  const after = { identity: await jsonSha(identity()), bytes: await jsonSha(await byteHashes()), gpuResources: { ...resourceCounts }, renderer: { geometries: renderer.info.memory.geometries, textures: renderer.info.memory.textures, programs: renderer.info.programs.length } };
  assert(JSON.stringify(before) === JSON.stringify(after), 'display identity/bytes/resource counts changed');
  renderer.setRenderTarget(null);
  renderer.render(scene, camera);
  gl.finish();
  const extension = gl.getExtension('WEBGL_debug_renderer_info');
  return {
    threeRevision: THREE.REVISION, width: 640, height: 480, antialias: false, shadows: 'PCF, 512x512 directional shadow map',
    fixture: { clusters: groups.length, instancesPerCluster: 4, occurrences: 192, trianglesPerGeometry, uniqueTriangles: trianglesPerGeometry * groups.length, occurrenceTriangles, insideClusters: [0, 1], crossingFrustumClusters: [2], shearedParentClusters: [3], offscreenClusters: 44 },
    warmupModes: warmup, rows, before, after, contributions,
    rendererInfo: { vendor: gl.getParameter(gl.VENDOR), renderer: gl.getParameter(gl.RENDERER), unmaskedVendor: extension ? gl.getParameter(extension.UNMASKED_VENDOR_WEBGL) : null, unmaskedRenderer: extension ? gl.getParameter(extension.UNMASKED_RENDERER_WEBGL) : null },
    assertions: { identicalFramebufferBytes: true, unchangedDisplayArraysAndIdentity: true, noGpuResourceChurnAfterWarmup: true, boundaryCasesContributePixels: true },
  };
}
window.runSurfaceCullingCheck = run;
window.disposeSurfaceCullingCheck = () => {
  for (const { sets, group, records, geometry } of groups) {
    dissolveCadSurfaceInstanceSets(sets, group);
    records.forEach(record => record.material.dispose());
    geometry.dispose();
  }
  floor.geometry.dispose(); floor.material.dispose();
  light.shadow.map?.dispose();
  target.dispose(); renderer.dispose(); renderer.forceContextLoss();
  return { setsDisposed: groups.every(({ set }) => set.disposed), resourceCounts: { ...resourceCounts } };
};
